```js
const fs = require('fs');
const path = require('path');
const { globSync } = require('glob');

function readJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
}

function normalizeLicense(license) {
  if (!license) return 'UNKNOWN';
  if (typeof license === 'string') return license;
  if (license.type) return license.type;
  if (Array.isArray(license)) return license.map(normalizeLicense).join(', ');
  return 'UNKNOWN';
}

function scanDependencies(projectRoot = process.cwd()) {
  const nodeModules = path.join(projectRoot, 'node_modules');
  if (!fs.existsSync(nodeModules)) {
    throw new Error('node_modules not found. Run npm install first.');
  }

  const packagePaths = globSync('**/package.json', {
    cwd: nodeModules,
    absolute: true,
    ignore: ['**/node_modules/**/node_modules/**'] // optional depth limit
  });

  return packagePaths.map(pkgPath => {
    const pkg = readJson(pkgPath);
    if (!pkg) return null;

    return {
      name: pkg.name,
      version: pkg.version,
      license: normalizeLicense(pkg.license),
      licenses: normalizeLicense(pkg.licenses),
      repository: pkg.repository?.url || pkg.repository || null,
      path: pkgPath
    };
  }).filter(Boolean);
}

module.exports = { scanDependencies };
```

