    console.error('Set LICENSE_API_URL and LICENSE_API_KEY');
    process.exit(1);
  }

  const report = {
    project: process.env.npm_package_name || require(path.join(process.cwd(), 'package.json')).name,
    timestamp: new Date().toISOString(),
    dependencies: scanDependencies()
