  "Version": "2012-10-17",
  "Statement": [
    {
      "Effect": "Allow",
      "Principal": {
        "AWS": "arn:aws:iam::TRUSTED-ACCOUNT-ID:role/RedTeamRole"
      },
      "Action": "sts:AssumeRole",
      "Condition": {
        "StringEquals": {
          "sts:ExternalId": "YOUR-UNIQUE-EXTERNAL-ID"
        }
      }
    }
  ]
}
```

And attach a **least-privilege permissions policy**, not `AdministratorAccess`, unless absolutely required and time-bound.

---

## 3. Detection script: audit risky assume-role trust policies

This Python script (using `boto3`) scans your account for IAM roles whose trust policies allow `sts:AssumeRole` from external accounts without an `ExternalId` or other strong conditions.

```python
import json
import boto3
import re

iam = boto3.client("iam")
MY_ACCOUNT = boto3.client("sts").get_caller_identity()["Account"]

def get_external_accounts(policy_doc):
    accounts = set()
    for stmt in policy_doc.get("Statement", []):
        if stmt.get("Effect") != "Allow":
            continue
        actions = stmt.get("Action", [])
        if isinstance(actions, str):
            actions = [actions]
        if not any("sts:AssumeRole" in a for a in actions):
            continue

        principals = stmt.get("Principal", {})
        aws_principals = principals.get("AWS", [])
        if isinstance(aws_principals, str):
            aws_principals = [aws_principals]

        for arn in aws_principals:
            match = re.search(r"arn:aws:iam::(\d+):", arn)
            if match:
                accounts.add(match.group(1))
    return accounts

def main():
    paginator = iam.get_paginator("list_roles")
    for page in paginator.paginate():
        for role in page["Roles"]:
            name = role["RoleName"]
            doc = role["AssumeRolePolicyDocument"]
            external_accounts = get_external_accounts(doc)

            for acct in external_accounts:
                if acct != MY_ACCOUNT:
                    conditions = json.dumps(doc.get("Statement", []))
                    has_external_id = "sts:ExternalId" in conditions
                    print(
                        f"[!] Role '{name}' trusts external account {acct}. "
                        f"ExternalId present: {has_external_id}"
                    )

if __name__ == "__main__":
    main()
